bafa-13422d948874", "cbc:IssueDate": "2024-06-14Z", "cbc:IssueTime": "14:45:37Z", "cbc:VersionID": "01", "cbc:RegulatoryDomain": "32014L0024", "cbc:NoticeTypeCode": {"@listName": "competition", "#text": "cn-desg"}, "cbc:NoticeLanguageCode": {"@listName": "language", "#text": "FRA"}, "cac:ContractingParty": {"cac:ContractingPartyType": {"cbc:PartyTypeCode": {"@listName": "buyer-legal-type", "#text": "body-pl"}}, "cac:ContractingActivity": {"cbc:ActivityTypeCode": {"@listName": "authority-activity", "#text": "health"}}, "cac:Party": {"cac:PartyIdentification": {"cbc:ID": "ORG-0001"}}}, "cac:TenderingTerms": {"cac:TendererQualificationRequest": {"cac:SpecificTendererRequirement": {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "nati-ground"}, "cbc:Description": {"@languageID": "FRA", "#text": "les autres motifs d'exclusion figurent à l'article L2141-1 à L2141-14 du Code de la commande publique. Les documents à fournir sont indiquées dans le règlement de la consultation"}}}}, "cac:TenderingProcess": {"cbc:Description": {"@languageID": "FRA", "#text": "Concours restreint -phase candidature ( articles L. 2125-1-2°, R. 2122-6,  R. 2162-15 à R. 2162-21 et R. 2172-2 du code de la commande publique)"}, "cbc:ProcedureCode": {"@listName": "procurement-procedure-type", "#text": "restricted"}}, "cac:ProcurementProject": {"cbc:Name": {"@languageID": "FRA", "#text": "MAITRISE D’ŒUVRE POUR LA CONSTRUCTION D’UN BATIMENT EFS SUR L’ILE DE NANTES"}, "cbc:Description": {"@languageID": "FRA", "#text": "prestation de maitrise d’œuvre pour la construction d’un bâtiment regroupant les activités Nantaises de prélèvement, d’immunohématologie, de distribution, de délivrance, de centre de soins, de HLA, de recherche, et les services supports de l’EFS CPDL, sur l’ile de Nantes"}, "cbc:ProcurementTypeCode": {"@listName": "contract-nature", "#text": "services"}, "cbc:Note": {"@languageID": "FRA", "#text": "La liste des candidats admis à remettre un projet sera établie, après avis du jury, à l'issue de l'examen des candidatures effectué dans les conditions définies dans le règlement de consultation. Seuls les quatre (4) candidats les mieux classés sur la base des critères énoncés dans le règlement de consultation seront retenus et admis à remettre un projet. Les candidats non retenus en seront informés par l'EFS. Une lettre de consultation, à laquelle sera joint le dossier de consultation des concepteurs, sera ensuite adressée aux candidats sélectionnés pour les inviter à remettre leur projet. Les candidats admis à remettre un projet devront obligatoirement visiter le site sur lequel la construction sera édifiée. Conformément à l'article R. 2172-2 du code de la commande publique, une fois que le(s) lauréat(s) a(ont) été désigné(s) sur la base de l'avis du jury dans les conditions définies dans le règlement de consultation, la négociation du marché public de maîtrise d'œuvre sera conduite selon la procédure de marché sans publicité ni mise en concurrence. Ce marché sans publicité ni mise en concurrence sera passé sur la base des articles L.2122-1 et R.2122-6 du Code de la commande publique. Les candidats sont toutefois informés du fait que l'acheteur se réserve le droit de ne pas donner suite au concours suite à la désignation du ou des lauréats"}, "cac:MainCommodityClassification": {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "71240000"}}}, "cac:ProcurementProjectLot": {"cbc:ID": {"@schemeName": "Lot", "#text": "LOT-0001"}, "cac:TenderingTerms": {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:SelectionCriteria": [{"cbc:CriterionTypeCode": {"@listName": "selection-criterion", "#text": "other"}, "cbc:Name": {"@languageID": "FRA", "#text": "Critère n°1: Capacités techniques et financières du candidat."}, "cbc:Description": {"@languageID": "FRA", "#text": "L'acheteur analysera les capacités économiques et techniques du candidat au travers de ses moyens en personnels et de son chiffre d'affaires"}, "cbc:CalculationExpressionCode": {"@listName": "usage", "#text": "used"}, "efbc:SecondStageIndicator": "true"}, {"cbc:CriterionTypeCode": {"@listName": "selection-criterion", "#text": "tp-abil"}, "cbc:Name": {"@languageID": "FRA", "#text": "Critère n°2 Capacités professionnelles du candidat évaluées sur la base des compétences qu'il assume et présente"}, "cbc:Description": {"@languageID": "FRA", "#text": "L'acheteur vérifiera que les qualifications et compétences nécessaires pour la bonne exécution du marché sont assumées et effectivement présentées par les candidats"}, "cbc:CalculationExpressionCode": {"@listName": "usage", "#text": "used"}, "efbc:SecondStageIndicator": "true"}, {"cbc:CriterionTypeCode": {"@listName": "selection-criterion", "#text": "tp-abil"}, "cbc:Name": {"@languageID": "FRA", "#text": "Critère n°3 Capacités professionnelles du candidat évaluées sur la base des références qu'il présente"}, "cbc:Description": {"@languageID": "FRA", "#text": "Ces dernières seront appréciées sur le fondement des 4 références énoncées à l'article 1.12.4 du Réglement de consultation au regard de la pertinence des opérations décrites compte-tenu des caractéristiques de l'opération projetée. Seront ainsi notamment appréciées les références relatives à des opérations : -De taille et 
d'envergure de travaux similaires; -De complexité équivalente et de préférence dans le domaine des laboratoires et de la santé -Relatives à des établissements recevant du public -Pour le compte d'une Maîtrise d'Ouvrage Publique"}, "cbc:CalculationExpressionCode": {"@listName": "usage", "#text": "used"}, "efbc:SecondStageIndicator": "true"}]}}}}, "cbc:VariantConstraintCode": {"@listName": "permission", "#text": "not-allowed"}, "cbc:FundingProgramCode": {"@listName": "eu-funded", "#text": "no-eu-funds"}, "cac:CallForTendersDocumentReference": {"cbc:ID": "2023EFS-CPDL254", "cbc:DocumentType": "non-restricted-document", "cac:Attachment": {"cac:ExternalReference": {"cbc:URI": "https://www.marches-publics.gouv.fr"}}}, "cac:ContractExecutionRequirement": {"cbc:ExecutionRequirementCode": {"@listName": "esignature-submission", "#text": "true"}}, "cac:AwardingTerms": {"cbc:FollowupContractIndicator": "true", "cbc:BindingOnBuyerIndicator": "false", "cac:AwardingCriterion": {"cac:SubordinateAwardingCriterion": [{"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:AwardCriterionParameter": {"efbc:ParameterCode": {"@listName": "number-weight", "#text": "per-exa"}, "efbc:ParameterNumeric": "40"}}}}}, "cbc:AwardingCriterionTypeCode": {"@listName": "award-criterion-type", "#text": "quality"}, "cbc:Description": {"@languageID": "FRA", "#text": "Critère 1: Qualités fonctionnelles -L'organisation spatiale, le respect des liaisons/flux, ainsi que la fonctionnalité globale de l'ouvrage ; -Le fonctionnement général des unités et l'adéquation au programme fonctionnel des espaces -Le respect des surfaces"}}, {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:AwardCriterionParameter": {"efbc:ParameterCode": {"@listName": "number-weight", "#text": "per-exa"}, "efbc:ParameterNumeric": "35"}}}}}, "cbc:AwardingCriterionTypeCode": {"@listName": "award-criterion-type", "#text": "quality"}, "cbc:Description": {"@languageID": "FRA", "#text": "Critère 2: Qualités architecturale, technique et environnementale - La qualité du projet architectural : le respect de l'insertion urbaine, des prescriptions urbaines, architecturales et paysagères (volumétrie, traitement des rez-de-chaussée, qualité des façades et toitures, qualité du coeur d'ilot, ambiances intérieures , ) - La qualité technique (parti constructif, propositions techniques, choix des matériaux, maintenance et exploitation) - La réponse aux ambitions environnementales, l'intégration des ambitions spécifiques et la pertinence des propositions du candidat pour tenir ces ambitions"}}, {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:AwardCriterionParameter": {"efbc:ParameterCode": {"@listName": "number-weight", "#text": "per-exa"}, "efbc:ParameterNumeric": "20"}}}}}, "cbc:AwardingCriterionTypeCode": {"@listName": "award-criterion-type", "#text": "cost"}, "cbc:Description": {"@languageID": "FRA", "#text": "Critère 3: Qualités financières :-L'adéquation du coût travaux au regard de l'enveloppe du maitre d'ouvrage et la cohérence du montant des travaux en lien avec les prestations proposées ; -Performance de l'économie globale du projet (coût prévisionnel des travaux et exploitation /maintenance)"}}, {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efac:AwardCriterionParameter": {"efbc:ParameterCode": {"@listName": "number-weight", "#text": "per-exa"}, "efbc:ParameterNumeric": "5"}}}}}, "cbc:AwardingCriterionTypeCode": {"@listName": "award-criterion-type", "#text": "quality"}, "cbc:Description": {"@languageID": "FRA", "#text": "Critère 4:Pertinence du planning :Cohérence du planning proposé (délais d'études et de réalisation) et adéquation avec le calendrier prévisionnel de l'opération défini par le maitre d'ouvrage"}}]}, "cac:TechnicalCommitteePerson": [{"cbc:FamilyName": "à voix Délibérative:- un(e) représentant(e) 